<?php $credits = get_option('mg_image_credits', array()); if ($credits) { ?><details class="mg-photo-credits section"><summary>대표 사진 출처와 라이선스</summary><p>사진은 예시 기사의 대표 이미지입니다. 원본 사진은 아래 출처와 라이선스를 확인해 주세요. 화면용 크기 조절·WebP 변환이 적용되었습니다.</p><ul><?php foreach ($credits as $image) { ?><li><?php echo esc_html(($image['alt'] ?? '') . ' · ' . ($image['credit'] ?? '')); if (!empty($image['source'])) echo ' · <a href="' . esc_url($image['source']) . '" target="_blank" rel="noopener noreferrer">원본</a>'; if (!empty($image['licenseUrl'])) echo ' · <a href="' . esc_url($image['licenseUrl']) . '" target="_blank" rel="noopener noreferrer">' . esc_html($image['license'] ?? '라이선스') . '</a>'; ?></li><?php } ?></ul></details><?php } ?>
<footer class="site-footer"><div class="footer-top"><?php echo mg_theme_wordmark(); ?><p>강진을 더 깊이.<br>일상을 더 가까이.</p><a href="#top" class="back-top" aria-label="맨 위로">↑</a></div><div class="footer-middle"><nav aria-label="매거진 안내"><?php foreach (array('about' => '매거진 소개','subscribe' => '정기 구독','institutions' => '기관 구독','advertise' => '광고·협업','contact' => '문의하기') as $path => $label) { ?><a href="<?php echo esc_url(mg_theme_url($path . '/')); ?>"><?php echo esc_html($label); ?></a><?php } ?></nav><div class="footer-contact"><span>LET'S TALK</span><a href="mailto:<?php echo esc_attr($settings['email']); ?>"><?php echo esc_html($settings['email']); ?> ↗</a><?php foreach ($settings['social'] as $label => $url) if ($url) { ?><a href="<?php echo esc_url($url); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html($label); ?> ↗</a><?php } ?></div></div><div class="publisher-info"><?php foreach (array('publisher' => '발행인','editor' => '편집인','address' => '주소','businessNumber' => '사업자등록번호','registrationNumber' => '등록번호','issn' => 'ISSN','phone' => '전화') as $key => $label) if (!empty($settings['footer'][$key])) echo '<span>' . esc_html($label . ' ' . $settings['footer'][$key]) . '</span>'; if (empty($settings['footer']['registrationNumber'])) echo '<span>발행·사업자 등록 정보와 판매 조건은 운영자가 확정 후 공개합니다.</span>'; ?></div><div class="footer-bottom"><span>© <?php echo esc_html(wp_date('Y') . ' ' . $settings['name']); ?>. ALL RIGHTS RESERVED.</span><nav aria-label="정책"><?php foreach (array('privacy' => '개인정보 처리방침','terms' => '이용약관','email' => '이메일 무단수집 거부','subscription' => '구독 안내','refund' => '취소·환불') as $key => $label) { ?><a href="<?php echo esc_url(mg_theme_url('policies/' . $key . '/')); ?>"><?php echo esc_html($label); ?></a><?php } ?></nav></div></footer>
